package com.samadhansetu.controller;
import com.samadhansetu.Service.DepartmentService; import com.samadhansetu.dto.*; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/departments") @RequiredArgsConstructor public class DepartmentController{private final DepartmentService service;@PostMapping public ResponseEntity<DepartmentResponseDto> create(@RequestBody DepartmentRequestDto r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@GetMapping public List<DepartmentResponseDto> all(){return service.all();}@GetMapping("/{id}") public DepartmentResponseDto get(@PathVariable Long id){return service.get(id);}@GetMapping("/university/{universityId}") public List<DepartmentResponseDto> byUniversity(@PathVariable Long universityId){return service.byUniversity(universityId);}@GetMapping("/search") public List<DepartmentResponseDto> search(@RequestParam String name){return service.search(name);}@PutMapping("/{id}") public DepartmentResponseDto update(@PathVariable Long id,@RequestBody DepartmentRequestDto r){return service.update(id,r);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();}}
